import math
# Pick angles in (0,180) to ensure Im(z), Im(w) > 0 when z=e^{iα}, w=e^{iβ}
# Choose m large to increase difficulty and require identities.
special = {0, 30, 36, 45, 60, 72, 90, 108, 120, 135, 144, 150, 180, 210, 225, 240, 270, 300, 315, 330}
for _ in range(10000):
    deg_a = rng.randint(1, 179)
    deg_b = rng.randint(1, 179)
    m = rng.randint(200, 5000)
    total = (deg_a + deg_b)
    # avoid α+β being a multiple of 180°, which would trivialize the cosine
    if total % 180 == 0:
        continue
    phi = (m * total) % 360
    # avoid trivially special angles for phi
    if phi in special:
        continue
    val = 2 * math.cos(math.radians(phi))
    # ensure not too close to an integer for numerical stability and non-triviality
    nearest = round(val)
    dist = abs(val - nearest)
    if dist < 0.05 or dist > 0.95:
        continue
    # also avoid being too close to boundaries where ceil changes unpredictably with tiny perturbations
    # e.g., near -2 or 2; ensure |val| <= 1.9 to be safe
    if abs(val) > 1.9:
        continue
    return {'deg_a': deg_a, 'deg_b': deg_b, 'm': m}
# Fallback deterministic hard instance if random attempts fail
deg_a, deg_b, m = 17, 43, 911
return {'deg_a': deg_a, 'deg_b': deg_b, 'm': m}

